using EFootwear.DAL.Persistence;
using EFootwear.Domain.CashManagement;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace EFootwear.DAL.CashManagement.Configurations;

/// <summary>Maps <see cref="CashCount"/> to cash.cash_counts. The difference column is generated by the database and is read only.</summary>
public sealed class CashCountConfiguration : IEntityTypeConfiguration<CashCount>
{
    public void Configure(EntityTypeBuilder<CashCount> builder)
    {
        builder.ToTable("cash_counts", "cash");
        builder.HasKey(count => new { count.CompanyId, count.Id });
        builder.Property(count => count.Id).ValueGeneratedOnAdd().HasDefaultValueSql("uuidv7()");
        builder.Property(count => count.DifferenceAmount).HasColumnName("difference").HasComputedColumnSql("counted_cash - expected_cash", stored: true);
        builder.Property(count => count.CreatedAt).ValueGeneratedOnAdd().HasDefaultValueSql("now()");
        builder.ConfigureRowVersionConcurrencyToken();
    }
}
